The diagnostic found the real source of the discrepancy:
discover-project inventory       5
actual rendered Master OS links  41
scroll container                 NAV
scrollHeight                     3434
clientHeight                     739
So Master OS has at least 41 conversations already present in the authenticated Safari DOM. The current discover-project logic is undercounting them. Do not authorize or capture Master OS yet.
Proceed with M51.4h-2b2c7a — exhaustive project discovery. Replace discoverProject() so it explicitly interrogates the project’s scrollable NAV, accumulates every matching conversation across scroll positions, and stops only after reaching the bottom with a stable count.
Bashcd /Users/erictouko/dev/korelumina

python3 - <<'PY'
from pathlib import Path

path = Path(
    "scripts/genesis-chatgpt-browser-recovery.mjs"
)

text = path.read_text()

start = text.find(
    "function discoverProject() {"
)

end = text.find(
    "\n\nfunction captureCurrentSnapshot(",
    start,
)

if start == -1:
    raise SystemExit(
        "discoverProject() anchor not found"
    )

if end == -1:
    raise SystemExit(
        "discoverProject() end anchor not found"
    )

replacement = r'''function discoverProject() {
  const projectStateRaw =
    runSafariJavaScript(
      `JSON.stringify((() => {
        const segments =
          location.pathname
            .split("/")
            .filter(Boolean);

        const gIndex =
          segments.indexOf(
            "g"
          );

        const rawProjectSegment =
          gIndex >= 0
            ? segments[
                gIndex + 1
              ]
            : null;

        const match =
          String(
            rawProjectSegment ??
            "",
          ).match(
            /^(g-p-[0-9a-f]{32})/i,
          );

        if (
          !match
        ) {
          throw new Error(
            "chatgpt_browser_recovery_not_in_project"
          );
        }

        return {
          projectId:
            match[1],

          projectTitle:
            document.title
              ?.replace(
                /\s*[|\-]\s*ChatGPT\s*$/i,
                ""
              )
              .split(" - ")[0]
              .trim() ||
            match[1],

          pageUrl:
            location.href,
        };
      })())`,
    );

  let projectState;

  try {
    projectState =
      JSON.parse(
        projectStateRaw,
      );
  } catch {
    fail(
      `Safari returned invalid project identity JSON:\n${projectStateRaw}`,
    );
  }

  const projectId =
    projectState.projectId;

  const conversations =
    new Map();

  let previousCount =
    -1;

  let stableBottomPasses =
    0;

  for (
    let pass =
      0;
    pass <
      80;
    pass +=
      1
  ) {
    const raw =
      runSafariJavaScript(
        `JSON.stringify((() => {
          const projectId =
            ${JSON.stringify(projectId)};

          const selector =
            'a[href*="/g/' +
            projectId +
            '/c/"]';

          const links =
            Array.from(
              document.querySelectorAll(
                selector
              )
            );

          const records =
            links
              .map(
                anchor => {
                  let url;

                  try {
                    url =
                      new URL(
                        anchor.href
                      );
                  } catch {
                    return null;
                  }

                  const segments =
                    url.pathname
                      .split("/")
                      .filter(Boolean);

                  const cIndex =
                    segments.lastIndexOf(
                      "c"
                    );

                  const rawConversationId =
                    cIndex >= 0
                      ? segments[
                          cIndex + 1
                        ]
                      : null;

                  if (
                    !rawConversationId
                  ) {
                    return null;
                  }

                  return {
                    conversationId:
                      decodeURIComponent(
                        rawConversationId
                      ),

                    title:
                      (
                        anchor.innerText ||
                        anchor.textContent ||
                        ""
                      ).trim(),

                    conversationUrl:
                      url.origin +
                      url.pathname,
                  };
                }
              )
              .filter(Boolean);

          let scrollContainer =
            null;

          for (
            const link
            of links
          ) {
            let node =
              link.parentElement;

            while (
              node
            ) {
              const style =
                getComputedStyle(
                  node
                );

              if (
                (
                  style.overflowY ===
                    "auto" ||
                  style.overflowY ===
                    "scroll"
                ) &&
                node.scrollHeight >
                  node.clientHeight +
                  2
              ) {
                scrollContainer =
                  node;

                break;
              }

              node =
                node.parentElement;
            }

            if (
              scrollContainer
            ) {
              break;
            }
          }

          if (
            !scrollContainer
          ) {
            return {
              records,
              scrollable:
                false,
              scrollTop:
                0,
              scrollHeight:
                0,
              clientHeight:
                0,
              atBottom:
                true,
            };
          }

          const before =
            scrollContainer.scrollTop;

          const next =
            Math.min(
              scrollContainer.scrollHeight -
                scrollContainer.clientHeight,
              before +
                Math.max(
                  250,
                  Math.floor(
                    scrollContainer.clientHeight *
                    0.75
                  )
                )
            );

          scrollContainer.scrollTop =
            next;

          return {
            records,

            scrollable:
              true,

            scrollTop:
              scrollContainer.scrollTop,

            scrollHeight:
              scrollContainer.scrollHeight,

            clientHeight:
              scrollContainer.clientHeight,

            atBottom:
              scrollContainer.scrollTop +
                scrollContainer.clientHeight >=
              scrollContainer.scrollHeight -
                4,
          };
        })())`,
      );

    let state;

    try {
      state =
        JSON.parse(
          raw,
        );
    } catch {
      fail(
        `Safari returned invalid exhaustive discovery JSON:\n${raw.slice(0, 1000)}`,
      );
    }

    for (
      const conversation
      of state.records ??
      []
    ) {
      const existing =
        conversations.get(
          conversation.conversationId,
        );

      /*
       * Prefer a meaningful human-readable title when the same
       * conversation is encountered more than once.
       */
      if (
        !existing ||
        (
          (
            !existing.title ||
            existing.title ===
              existing.conversationId
          ) &&
          conversation.title
        )
      ) {
        conversations.set(
          conversation.conversationId,
          conversation,
        );
      }
    }

    const currentCount =
      conversations.size;

    console.log(
      `[discover] pass=${pass + 1} conversations=${currentCount} scrollTop=${state.scrollTop} scrollHeight=${state.scrollHeight} bottom=${state.atBottom}`,
    );

    if (
      state.atBottom
    ) {
      if (
        currentCount ===
          previousCount
      ) {
        stableBottomPasses +=
          1;
      } else {
        stableBottomPasses =
          0;
      }

      /*
       * Two stable observations at the bottom are required before
       * accepting the inventory. This gives ChatGPT time to lazy-load
       * another batch after reaching the apparent bottom.
       */
      if (
        stableBottomPasses >=
          2
      ) {
        break;
      }

      /*
       * Nudge upward and back down on the next pass. Virtualized
       * sidebars sometimes materialize another batch only after an
       * additional scroll event.
       */
      runSafariJavaScript(
        `(() => {
          const projectId =
            ${JSON.stringify(projectId)};

          const link =
            document.querySelector(
              'a[href*="/g/' +
              projectId +
              '/c/"]'
            );

          if (!link) {
            return;
          }

          let node =
            link.parentElement;

          while (node) {
            const style =
              getComputedStyle(
                node
              );

            if (
              (
                style.overflowY ===
                  "auto" ||
                style.overflowY ===
                  "scroll"
              ) &&
              node.scrollHeight >
                node.clientHeight +
                2
            ) {
              node.scrollTop =
                Math.max(
                  0,
                  node.scrollTop -
                    Math.floor(
                      node.clientHeight *
                      0.5
                    )
                );

              return;
            }

            node =
              node.parentElement;
          }
        })()`,
      );
    }

    previousCount =
      currentCount;

    sleep(
      600,
    );
  }

  /*
   * One final collection after scrolling has stabilized.
   */
  const finalRaw =
    runSafariJavaScript(
      `JSON.stringify(
        Array.from(
          document.querySelectorAll(
            'a[href*="/g/${projectId}/c/"]'
          )
        ).map(anchor => ({
          href:
            anchor.href,
          title:
            (
              anchor.innerText ||
              anchor.textContent ||
              ""
            ).trim()
        }))
      )`,
    );

  try {
    const finalLinks =
      JSON.parse(
        finalRaw,
      );

    for (
      const item
      of finalLinks
    ) {
      const url =
        new URL(
          item.href,
        );

      const segments =
        url.pathname
          .split("/")
          .filter(Boolean);

      const cIndex =
        segments.lastIndexOf(
          "c",
        );

      if (
        cIndex < 0 ||
        !segments[
          cIndex + 1
        ]
      ) {
        continue;
      }

      const conversationId =
        decodeURIComponent(
          segments[
            cIndex + 1
          ],
        );

      conversations.set(
        conversationId,
        {
          conversationId,

          title:
            item.title ||
            conversations.get(
              conversationId,
            )?.title ||
            conversationId,

          conversationUrl:
            url.origin +
            url.pathname,
        },
      );
    }
  } catch {
    // The accumulated inventory remains authoritative for this run.
  }

  const normalized =
    [
      ...conversations.values(),
    ]
      .sort(
        (
          left,
          right,
        ) =>
          left.title.localeCompare(
            right.title,
          ) ||
          left.conversationId.localeCompare(
            right.conversationId,
          ),
      );

  if (
    normalized.length ===
      0
  ) {
    fail(
      "No project conversations were discovered.",
    );
  }

  const inventory = {
    inventoryVersion:
      "chatgpt-browser-project-inventory:v1",

    projectId,

    projectTitle:
      projectState.projectTitle,

    discoveredAt:
      Date.now(),

    pageUrl:
      projectState.pageUrl,

    conversationCount:
      normalized.length,

    conversations:
      normalized,
  };

  const destination =
    persistProjectInventory(
      inventory,
    );

  console.log(
    JSON.stringify(
      {
        ok:
          true,

        browser:
          "Safari",

        destination,

        projectId:
          inventory.projectId,

        projectTitle:
          inventory.projectTitle,

        conversationCount:
          inventory.conversationCount,

        conversations:
          inventory.conversations,
      },
      null,
      2,
    ),
  );
}
'''

path.write_text(
    text[:start] +
    replacement +
    text[end:]
)
PY

node --check scripts/genesis-chatgpt-browser-recovery.mjs
git diff --check
